import{_ as o,o as e,c as a,a2 as r}from"./chunks/framework.BUOFcz_J.js";const s="/Rho/docs/assets/rho-0.5.10-studio-five-views.C7G-KmKA.png",g=JSON.parse('{"title":"Rho 0.5.10 人类教程：把一次分析放进同一个工作区","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rho-0-5-10-tutorial.md","filePath":"reference/rho-0-5-10-tutorial.md"}'),d={name:"reference/rho-0-5-10-tutorial.md"};function i(l,t,h,n,c,p){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="rho-0-5-10-人类教程-把一次分析放进同一个工作区" tabindex="-1">Rho 0.5.10 人类教程：把一次分析放进同一个工作区 <a class="header-anchor" href="#rho-0-5-10-人类教程-把一次分析放进同一个工作区" aria-label="Permalink to &quot;Rho 0.5.10 人类教程：把一次分析放进同一个工作区&quot;">​</a></h1><p>这篇教程写给坐在浏览器前的人。安装和启动由 Agent 完成，人从项目页面开始：先看问题和数据，再看代码和 Notebook，接着把输入、代码、结果和笔记放进 Studio，最后回到 Graph 看这次工作留下了什么。</p><p>我用 Rho 0.5.10 新建了一套专门的演示项目，把完整路径走了一遍。项目回答一个很小但完整的问题：<strong>在 5 天观察期内，treated 组的 score 是否超过 control 组？</strong></p><h2 id="_1、先看这套完整的-rho-教程" tabindex="-1">1、先看这套完整的 Rho 教程 <a class="header-anchor" href="#_1、先看这套完整的-rho-教程" aria-label="Permalink to &quot;1、先看这套完整的 Rho 教程&quot;">​</a></h2><h3 id="_1-1-这-5-个入口各做什么" tabindex="-1">1.1 这 5 个入口各做什么 <a class="header-anchor" href="#_1-1-这-5-个入口各做什么" aria-label="Permalink to &quot;1.1 这 5 个入口各做什么&quot;">​</a></h3><p>第一次打开 Rho，先不要把它当成一个只能显示文件的网页。一个项目里的入口各自负责一件事，合起来才是完整工作流。</p><table tabindex="0"><thead><tr><th>入口</th><th>这次演示里看到什么</th><th>人要做什么</th></tr></thead><tbody><tr><td><strong>Projects</strong></td><td><code>Rho 教程演示 0.5.10</code></td><td>选对项目，确认自己没有进错文件夹</td></tr><tr><td><strong>Sources</strong></td><td>Data、Code、Results &amp; figures、Notes</td><td>按资源类型找输入、脚本、结果和笔记</td></tr><tr><td><strong>Notebook</strong></td><td>Python 3.13.1、4 个 cell、输出和图</td><td>看每次运行的代码、输出、时间和触发者</td></tr><tr><td><strong>Studio</strong></td><td><code>summarize.py</code>、Notebook、<code>growth.csv</code>、汇总表、PNG 图</td><td>把一次工作的关键视图放到同一屏里</td></tr><tr><td><strong>Graph</strong></td><td>1 条 Notebook 工作线、4 个步骤和时间线动作</td><td>回看这次工作做过什么，不替没有发生的 Agent 工作编故事</td></tr></tbody></table><p>左侧还会看到 <strong>Plugins</strong>、<strong>Project settings</strong> 和 <strong>Agent</strong>。Plugins 是能力入口，Project settings 是项目配置，Agent 是可选的协作者；这篇教程的主路径先由人走通，不依赖 Agent 对话。</p><h3 id="_1-2-这次演示的文件" tabindex="-1">1.2 这次演示的文件 <a class="header-anchor" href="#_1-2-这次演示的文件" aria-label="Permalink to &quot;1.2 这次演示的文件&quot;">​</a></h3><p>项目在：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>~/Rho/projects/Rho 教程演示 0.5.10</span></span></code></pre></div><p>文件只有几类，但每一类都有用途：</p><table tabindex="0"><thead><tr><th>位置</th><th>文件</th><th>作用</th></tr></thead><tbody><tr><td>Data</td><td><code>data/growth.csv</code></td><td>10 行观测，两个组、五个时间点</td></tr><tr><td>Code</td><td><code>analysis/summarize.py</code></td><td>读入数据、分组汇总、写结果、画图</td></tr><tr><td>Results &amp; figures</td><td><code>results/group_summary.csv</code></td><td>两组的均值、day 5 分数和峰值</td></tr><tr><td>Results &amp; figures</td><td><code>results/group_summary.png</code></td><td>两组五天变化曲线</td></tr><tr><td>Notes</td><td><code>project-notes.md</code></td><td>Question、Data &amp; method、Key results、Choices、Files、To do</td></tr></tbody></table><h3 id="_1-3-开始前准备什么" tabindex="-1">1.3 开始前准备什么 <a class="header-anchor" href="#_1-3-开始前准备什么" aria-label="Permalink to &quot;1.3 开始前准备什么&quot;">​</a></h3><p>请让 Agent 在浏览器中打开这个项目即可：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>请在浏览器中打开 Rho 的“Rho 教程演示 0.5.10”项目。这篇教程写给我本人：我会在页面里点 Projects、Data、Code、Notebook、Studio、Notes 和 Graph，请不要让我使用命令行。</span></span></code></pre></div><p>浏览器打开后，在左侧 <strong>Projects</strong> 选择 <code>Rho 教程演示 0.5.10</code>。这篇教程不把安装命令当正文，因为安装和连接属于 Agent 的准备工作；人要学的是项目页面里的判断、操作和复核。</p><h2 id="_2、7-步走一遍完整-rho-工作流" tabindex="-1">2、7 步走一遍完整 Rho 工作流 <a class="header-anchor" href="#_2、7-步走一遍完整-rho-工作流" aria-label="Permalink to &quot;2、7 步走一遍完整 Rho 工作流&quot;">​</a></h2><h3 id="_2-1-第-1-步-先把问题立住" tabindex="-1">2.1 第 1 步：先把问题立住 <a class="header-anchor" href="#_2-1-第-1-步-先把问题立住" aria-label="Permalink to &quot;2.1 第 1 步：先把问题立住&quot;">​</a></h3><p>进入项目后，先读 Overview 和项目标题，确认这次要回答的是：</p><blockquote><p>在 5 天观察期内，treated 组的 score 是否超过 control 组？</p></blockquote><p>这一步的产出不是结论，而是一个可以由数据和结果回答的问题。问题如果不清楚，后面打开再多文件也只是浏览。</p><h3 id="_2-2-第-2-步-在-data-里读原始表" tabindex="-1">2.2 第 2 步：在 Data 里读原始表 <a class="header-anchor" href="#_2-2-第-2-步-在-data-里读原始表" aria-label="Permalink to &quot;2.2 第 2 步：在 Data 里读原始表&quot;">​</a></h3><p>展开左侧 <strong>Data</strong>，点击 <code>growth.csv</code>。Rho 会打开表格视图；实际页面显示 <strong>10 rows</strong>，4 列：<code>sample_id</code>、<code>group</code>、<code>day</code> 和 <code>score</code>。</p><p>先做三个检查：</p><ol><li><code>control</code> 和 <code>treated</code> 是否各有 5 行。</li><li><code>day</code> 是否覆盖 1 到 5。</li><li><code>score</code> 是否随天数变化。</li></ol><p>这时你已经能看到 day 5 的两个数：control 是 26，treated 是 38。但先把它当作观察，不要直接当成分析结论。后面还要看均值、峰值和图。</p><p>表格上方有 <strong>Explore in the Notebook</strong>。先不要点它，先把输入读懂；人知道输入是什么，Notebook 才有上下文。</p><h3 id="_2-3-第-3-步-在-code-里看数据怎样变成结果" tabindex="-1">2.3 第 3 步：在 Code 里看数据怎样变成结果 <a class="header-anchor" href="#_2-3-第-3-步-在-code-里看数据怎样变成结果" aria-label="Permalink to &quot;2.3 第 3 步：在 Code 里看数据怎样变成结果&quot;">​</a></h3><p>展开 <strong>Code</strong>，点击 <code>analysis/summarize.py</code>。代码视图里可以看到：</p><ul><li><code>DATA</code> 指向 <code>data/growth.csv</code>；</li><li><code>by_group</code> 按 <code>group</code> 收集行；</li><li><code>summary</code> 计算均值、day 5 分数和峰值；</li><li><code>RESULTS</code> 写出 CSV、Markdown 和 PNG。</li></ul><p>代码视图里的 <strong>Data flow</strong> 也可以打开。这次实际看到 <code>ROOT</code>、<code>RESULTS</code> 和 <code>group_summary.png</code> 等值的路径关系。Data flow 只读取代码来画关系，不会运行脚本。</p><p>这里的 <strong>Run</strong> 运行当前光标所在的语句或选中的代码。光标在第一行时，Run 只会跑这一行；要运行完整脚本，下一步使用 <strong>Explore in Python</strong>。</p><h3 id="_2-4-第-4-步-把输入带进-notebook" tabindex="-1">2.4 第 4 步：把输入带进 Notebook <a class="header-anchor" href="#_2-4-第-4-步-把输入带进-notebook" aria-label="Permalink to &quot;2.4 第 4 步：把输入带进 Notebook&quot;">​</a></h3><p>回到 <code>growth.csv</code>，点击表格上方的 <strong>Python</strong>。Rho 会自动：</p><ol><li>打开 Notebook 视图；</li><li>启动这个 Notebook 自己的 Python 会话；</li><li>加入一格加载 <code>growth.csv</code> 的代码。</li></ol><p>实际页面显示 Python 3.13.1，并给出 <code>(10, 4)</code> 和前几行。这个 cell 的记录带着 <strong>You</strong>、时间和输出，说明这一步是人从表格触发的。</p><p>Notebook 不是一个只显示最后结果的黑箱。每个 cell 都能看到代码、输出、运行时间、变量和图；后面的 cell 可以继续使用同一个 Notebook 会话里的值。</p><h3 id="_2-5-第-5-步-从-code-运行完整脚本" tabindex="-1">2.5 第 5 步：从 Code 运行完整脚本 <a class="header-anchor" href="#_2-5-第-5-步-从-code-运行完整脚本" aria-label="Permalink to &quot;2.5 第 5 步：从 Code 运行完整脚本&quot;">​</a></h3><p>回到 <code>summarize.py</code>，点击 <strong>Explore in Python</strong>。Rho 会把下面这段待确认代码放进 Notebook：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;">__file__</span><span style="--shiki-light:#D73A49;--shiki-dark:#D73A49;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> &quot;analysis/summarize.py&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;">exec</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;">compile</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;">open</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;">__file__</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">).read(), </span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;">__file__</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;">&quot;exec&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">))</span></span></code></pre></div><p>先读一遍，再按 <strong>Run</strong>。这次实际运行后，Notebook 记录了：</p><ul><li><code>results/group_summary.csv</code> 被写出；</li><li><code>results/group_summary.md</code> 被写出；</li><li><code>results/group_summary.png</code> 被写出；</li><li>一张图被绘制；</li><li>图里 10 个点与原始数据行保持绑定；</li><li>Python 会话里保留了脚本产生的变量。</li></ul><p>如果脚本缺少 Python 包，先读当前 cell 的错误，再决定是否让 Agent 帮忙准备环境。不要因为一格报错就删项目或重启整个服务。</p><h3 id="_2-6-第-6-步-在-results-figures-里复核结果" tabindex="-1">2.6 第 6 步：在 Results &amp; figures 里复核结果 <a class="header-anchor" href="#_2-6-第-6-步-在-results-figures-里复核结果" aria-label="Permalink to &quot;2.6 第 6 步：在 Results &amp; figures 里复核结果&quot;">​</a></h3><p>展开 <strong>Results &amp; figures</strong>，先打开 <code>group_summary.csv</code>。这次实际看到的是：</p><table tabindex="0"><thead><tr><th>group</th><th style="text-align:right;">n</th><th style="text-align:right;">mean_score</th><th style="text-align:right;">day_5_score</th><th style="text-align:right;">peak_day</th><th style="text-align:right;">peak_score</th></tr></thead><tbody><tr><td>control</td><td style="text-align:right;">5</td><td style="text-align:right;">20.0</td><td style="text-align:right;">26</td><td style="text-align:right;">5</td><td style="text-align:right;">26</td></tr><tr><td>treated</td><td style="text-align:right;">5</td><td style="text-align:right;">25.2</td><td style="text-align:right;">38</td><td style="text-align:right;">5</td><td style="text-align:right;">38</td></tr></tbody></table><p>再打开 <code>group_summary.png</code>。蓝线是 control，橙线是 treated；第 3 天以后两条线明显分开，treated 在第 5 天到达 38。</p><p>现在才写这次演示的结论：treated 在 day 5 比 control 高 12 分。这个结论只属于演示数据，项目笔记里也明确写了它不能支持真实实验结论。</p><p>如果你想追问一个具体点，可以在图上点或拖选 marks；Rho 会提示这个点对应哪一行，并提供向 Agent 提问的入口。人可以先自己判断，再决定要不要让 Agent 补充解释。</p><h3 id="_2-7-第-7-步-用-studio-把完整工作放到一屏" tabindex="-1">2.7 第 7 步：用 Studio 把完整工作放到一屏 <a class="header-anchor" href="#_2-7-第-7-步-用-studio-把完整工作放到一屏" aria-label="Permalink to &quot;2.7 第 7 步：用 Studio 把完整工作放到一屏&quot;">​</a></h3><p>这一步是 Rho 和普通文件浏览器最不一样的地方。</p><p>点击 <strong>Studio</strong>，把下面 5 个视图放进同一个 <strong>Workspace</strong>：</p><ol><li><code>summarize.py</code>；</li><li>Notebook；</li><li><code>growth.csv</code>；</li><li><code>group_summary.csv</code>；</li><li><code>group_summary.png</code>。</li></ol><p>这次实际的 Studio 有 5 views：左边是代码和 Data flow，中间是 Notebook，右边是结果图；<code>growth.csv</code> 和汇总表以 tabs 保留在同一组视图里。你可以拖动分隔线改变宽度，也可以在同一个视图组里切换数据表和结果表。</p><p><img src="`+s+'" alt="Rho 0.5.10 教程项目的五视图 Studio：代码、Notebook、数据表和 Project notes"></p><p>Studio 不是把文件复制成一张新报告，而是把原有资源的视图组合起来。关闭某个 tab 不会删除文件，关闭 Workspace 也不会删除项目、Notebook 或结果。</p><p>打开左侧 <strong>Notes</strong>，让 <code>project-notes.md</code> 作为右侧面板显示。这样人的 Question、Key results、Choices 和 To do 与 Studio 同屏，复核结果时不需要另开一个编辑器。</p><p>完成后再点 <strong>Graph</strong>。这次 Graph 会把 4 次由你触发的加载和运行收进一条 <strong>Notebook</strong> 工作线，下面的时间线还会标出这些动作和结果文件的变化。没有 Agent 对话，就不会凭空生成一条 Agent 工作线。</p><h2 id="_3、完整使用时-人在每个页面做什么" tabindex="-1">3、完整使用时，人在每个页面做什么 <a class="header-anchor" href="#_3、完整使用时-人在每个页面做什么" aria-label="Permalink to &quot;3、完整使用时，人在每个页面做什么&quot;">​</a></h2><h3 id="_3-1-projects-和-sources-确定范围" tabindex="-1">3.1 Projects 和 Sources：确定范围 <a class="header-anchor" href="#_3-1-projects-和-sources-确定范围" aria-label="Permalink to &quot;3.1 Projects 和 Sources：确定范围&quot;">​</a></h3><p>Projects 决定你在哪个项目里，Sources 决定你看输入、代码、结果还是笔记。先在这里确定范围，再进入 Studio。</p><h3 id="_3-2-notebook-确认运行真的发生过" tabindex="-1">3.2 Notebook：确认运行真的发生过 <a class="header-anchor" href="#_3-2-notebook-确认运行真的发生过" aria-label="Permalink to &quot;3.2 Notebook：确认运行真的发生过&quot;">​</a></h3><p>Notebook 保留每个 cell 的代码、输出、时间和触发者。它回答“哪一格跑了、跑出了什么”，而不是只给一个最终数字。</p><h3 id="_3-3-studio-安排一次工作的上下文" tabindex="-1">3.3 Studio：安排一次工作的上下文 <a class="header-anchor" href="#_3-3-studio-安排一次工作的上下文" aria-label="Permalink to &quot;3.3 Studio：安排一次工作的上下文&quot;">​</a></h3><p>Studio 把人当前要对照的东西放在一起。这次的 5 个 views 让你能同时看代码、数据、汇总表、图和 Notebook；换成自己的项目时，视图数量取决于当前问题。</p><p>一个项目可以放多个 Notebook。新建 Notebook 时，Rho 会给它一个不重复的默认名称（例如 <code>Notebook</code>、<code>Notebook 2</code>）；选中 Notebook 标签后，点击标签旁边的铅笔按钮即可改名。改名只改变这个视图在当前项目里的标题，不会清掉其中的 cell、输出或运行记录。</p><p>Overview 里的 Notebook 区块、时间线和右侧 Workspace 摘要会沿用这个标题。本教程项目把它命名为 <code>Growth analysis</code>，所以回到 Overview 时，三处都会显示这个名字。</p><h3 id="_3-4-notes-留下人的判断" tabindex="-1">3.4 Notes：留下人的判断 <a class="header-anchor" href="#_3-4-notes-留下人的判断" aria-label="Permalink to &quot;3.4 Notes：留下人的判断&quot;">​</a></h3><p>Notes 记录问题、方法、结果、选择、文件和下一步。结果表说“是多少”，Notes 说“为什么这样做、哪些限制仍然存在”。</p><h3 id="_3-5-graph-回看已经发生的动作" tabindex="-1">3.5 Graph：回看已经发生的动作 <a class="header-anchor" href="#_3-5-graph-回看已经发生的动作" aria-label="Permalink to &quot;3.5 Graph：回看已经发生的动作&quot;">​</a></h3><p>这次 Graph 不是一张空白画布。它会显示一条 <code>Notebook</code> 工作线、4 个 recorded steps，并把 <code>growth.csv</code>、<code>summarize.py</code>、汇总表和 PNG 图挂在这条线上。下面的时间线按时间放入 4 次 cell 运行和结果文件变化。</p><p>Graph 是回看工具，不是自动补全器；没有发生的 Agent 对话和没有记录的步骤不会被它编出来。</p><h3 id="_3-6-agent-在上下文准备好后再提问" tabindex="-1">3.6 Agent：在上下文准备好后再提问 <a class="header-anchor" href="#_3-6-agent-在上下文准备好后再提问" aria-label="Permalink to &quot;3.6 Agent：在上下文准备好后再提问&quot;">​</a></h3><p>这次演示没有启动 Agent 对话。你完成前面 6 步后，可以在结果表里选一行，再问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>只根据当前项目的 growth.csv、summarize.py 和 group_summary.csv，说明 treated 在 day 5 比 control 高多少；指出数字来自哪一列，并说明这份演示数据不能支持什么结论。</span></span></code></pre></div><p>这样 Agent 看到的是你已经读过的数据、代码、结果和 Notes，而不是一个没有上下文的空问题。</p><h2 id="_4、这篇教程里应该放哪些截图" tabindex="-1">4、这篇教程里应该放哪些截图 <a class="header-anchor" href="#_4、这篇教程里应该放哪些截图" aria-label="Permalink to &quot;4、这篇教程里应该放哪些截图&quot;">​</a></h2><p>参照新品教程的写法，截图只证明旁边那句话。准备这套 Rho 教程时，建议保留 6 张：</p><table tabindex="0"><thead><tr><th>截图</th><th>要证明什么</th></tr></thead><tbody><tr><td>Projects + 项目名</td><td>人进入的是专门的教程项目</td></tr><tr><td><code>growth.csv</code> 表格</td><td>Data 里有 10 行、4 列和两个组</td></tr><tr><td><code>summarize.py</code> + Data flow</td><td>Code 怎样读入、汇总和写出结果</td></tr><tr><td>Notebook</td><td>Python 3.13.1、cell、输出和绘图</td></tr><tr><td>5-view Studio + Notes</td><td>代码、Notebook、数据、汇总表、图和人的笔记同屏</td></tr><tr><td>Graph</td><td>1 条 Notebook 工作线、4 个步骤和时间线动作</td></tr></tbody></table><p>截图里不要放 connection 文件或任何凭据。项目内容可以保留，因为它是专门为教程准备的演示数据。</p><h2 id="_5、常见问题" tabindex="-1">5、常见问题 <a class="header-anchor" href="#_5、常见问题" aria-label="Permalink to &quot;5、常见问题&quot;">​</a></h2><h3 id="_5-1-为什么这篇教程不从命令行开始" tabindex="-1">5.1 为什么这篇教程不从命令行开始？ <a class="header-anchor" href="#_5-1-为什么这篇教程不从命令行开始" aria-label="Permalink to &quot;5.1 为什么这篇教程不从命令行开始？&quot;">​</a></h3><p>因为命令行安装和连接是 Agent 的准备工作。人使用 Rho 的主路径从浏览器里的 Projects 开始，重点是理解数据、代码、Notebook、Studio、结果、Notes 和 Graph 怎样连在一起。</p><h3 id="_5-2-studio-和打开几个文件有什么区别" tabindex="-1">5.2 Studio 和打开几个文件有什么区别？ <a class="header-anchor" href="#_5-2-studio-和打开几个文件有什么区别" aria-label="Permalink to &quot;5.2 Studio 和打开几个文件有什么区别？&quot;">​</a></h3><p>单独打开文件只是浏览。Studio 会把这些视图组成一个可继续工作的上下文：这次 5 个 views 保持代码、Notebook、数据、汇总表和图的关系，Notes 还能在旁边持续显示。</p><h3 id="_5-3-为什么我的-studio-里没有-5-个-views" tabindex="-1">5.3 为什么我的 Studio 里没有 5 个 views？ <a class="header-anchor" href="#_5-3-为什么我的-studio-里没有-5-个-views" aria-label="Permalink to &quot;5.3 为什么我的 Studio 里没有 5 个 views？&quot;">​</a></h3><p>打开项目后，先从 Sources 依次点开 <code>growth.csv</code>、<code>group_summary.csv</code> 和 <code>group_summary.png</code>，再从 Code 打开 <code>summarize.py</code>，从已有 Workspace 打开 Notebook。它们会加入当前 Workspace；不要每次都新建一个浏览器窗口。</p><h3 id="_5-4-为什么不同-notebook-的名字都一样-怎么改名" tabindex="-1">5.4 为什么不同 Notebook 的名字都一样？怎么改名？ <a class="header-anchor" href="#_5-4-为什么不同-notebook-的名字都一样-怎么改名" aria-label="Permalink to &quot;5.4 为什么不同 Notebook 的名字都一样？怎么改名？&quot;">​</a></h3><p>旧版本里，新建 Notebook 可能都显示为 <code>Notebook</code>，所以看起来像是同一个视图。0.5.10 会为后续 Notebook 使用 <code>Notebook 2</code>、<code>Notebook 3</code> 这样的不重复名称；已经存在的 Notebook 不会被自动改名。选中要改的 Notebook，在标签右侧点击铅笔按钮，输入新名称并确认即可；右键标签也能从菜单里选择 <strong>Rename notebook</strong>。</p><h3 id="_5-5-为什么-graph-里没有-agent-对话" tabindex="-1">5.5 为什么 Graph 里没有 Agent 对话？ <a class="header-anchor" href="#_5-5-为什么-graph-里没有-agent-对话" aria-label="Permalink to &quot;5.5 为什么 Graph 里没有 Agent 对话？&quot;">​</a></h3><p>因为这次演示没有启动 Agent 对话。Graph 仍会保留人的 Notebook 工作线：你触发的 4 次加载和运行会作为 4 个步骤出现；启动 Agent 后，再用同一个项目的 Agent 面板继续，Graph 才会增加对应的 Agent 记录。</p><h3 id="_5-6-没有-r-能不能完成这篇教程" tabindex="-1">5.6 没有 R 能不能完成这篇教程？ <a class="header-anchor" href="#_5-6-没有-r-能不能完成这篇教程" aria-label="Permalink to &quot;5.6 没有 R 能不能完成这篇教程？&quot;">​</a></h3><p>能。这套演示使用 Python。Rho 的浏览器、文件、Notes、Studio、Graph 和 Python Notebook 仍然可以使用；只有需要 R 的 cell 才需要 R 和相应的 R 包。</p><h3 id="_5-7-这份数据能证明真实实验结论吗" tabindex="-1">5.7 这份数据能证明真实实验结论吗？ <a class="header-anchor" href="#_5-7-这份数据能证明真实实验结论吗" aria-label="Permalink to &quot;5.7 这份数据能证明真实实验结论吗？&quot;">​</a></h3><p>不能。它只用来练习 Rho 的完整使用。真实项目要把数据来源、实验设计、缺失值处理、模型选择和不确定性写进 Notes，再由研究者判断结论范围。</p><h2 id="_6、完成标准" tabindex="-1">6、完成标准 <a class="header-anchor" href="#_6、完成标准" aria-label="Permalink to &quot;6、完成标准&quot;">​</a></h2><p>读者走完这篇教程后，应该能在浏览器中完成一次完整的 Rho 使用：</p><ul><li>在 Projects 进入正确项目；</li><li>从 Data 读懂原始表；</li><li>从 Code 和 Data flow 看懂输入到输出；</li><li>从表格把数据带进 Notebook；</li><li>从 Code 运行完整脚本；</li><li>在 Results &amp; figures 核对表和图；</li><li>在 Studio 里组合 5 个 views；</li><li>在 Notes 里写下结论、选择和限制；</li><li>在 Graph 里回看人的操作；</li><li>在上下文准备好后，再让 Agent 回答具体问题。</li></ul><p>这才是一次完整的 Rho 使用：人从问题开始，在同一个项目里完成数据、代码、Notebook、结果、Studio、Notes 和 Graph 的闭环。</p>',100)])])}const b=o(d,[["render",i]]);export{g as __pageData,b as default};
